EquipRegeneration = {}
EquipRegeneration.__index = EquipRegeneration

local this = {}

--- 生成再生词条
--- @param actor any 角色
--- @param msgData table 消息数据
function EquipRegeneration.regeneration(actor, msgData)
    -- 校验条件
    local itemId = msgData["itemId"]
    if string.isNullOrEmpty(itemId) then
        gameDebug.printTraceback("itemId为空")
        return
    end
    local equipInfo = getequipinfo(actor, itemId, 1)
    if table.isNullOrEmpty(equipInfo) then
        gameDebug.printTraceback("装备不存在")
        return
    end
    local itemCfgId = equipInfo["cfgid"]
    local tableInfo = ConfigDataManager.getById("cfg_equip_regeneration", tonumber(itemCfgId))
    if table.isNullOrEmpty(tableInfo) then
        noticeTip.noticeinfo(actor, StringIdConst.REGENERATION_CONDITION_FAIL)
        return
    end
    -- 判断道具是否充足
    local cost = tableInfo["start"]
    local costMap = string.toIntIntMap(cost)
    if not Bag.checkCostMap(actor, costMap) then
        noticeTip.noticeinfo(actor, StringIdConst.REGENERATION_CONDITION_FAIL)
        return
    end
    -- 判断再生条件是否满足
    local condition = tableInfo["condition"]
    if string.isNullOrEmpty(condition) then
        return
    end
    local strengthLevel = API.GetItemData(actor, itemId, "strengthlv")
    if tonumber(condition) > strengthLevel then
        noticeTip.noticeinfo(actor, StringIdConst.REGENERATION_CONDITION_FAIL)
        return
    end
    -- 再生词条写死只有一条，判断是否已经生成过再生词条，如果有则不能再生
    local regenerationData = API.GetItemData(actor, itemId, "regeneration")
    if table.notNullOrEmpty(regenerationData) then
        noticeTip.noticeinfo(actor, StringIdConst.REGENERATION_CONDITION_FAIL)
        return
    end
    -- 判断成功率
    local result, _ = this.checkRate(tableInfo["group"], 1)
    if result then
        this.regeneration(actor, itemId, tableInfo)
    end
    Bag.costMap(actor, costMap, ItemAction.EQUIP_REGENERATION_COST)
    sendluamsg(actor, LuaMessageIdToClient.RES_REGENERATION_RESULT, result)
end

--- 再生词条进化
--- @param actor any 角色
--- @param msgData table 消息数据
function EquipRegeneration.evolution(actor, msgData)
    -- 校验条件
    local itemId = msgData["itemId"]
    if string.isNullOrEmpty(itemId) then
        gameDebug.printTraceback("itemId为空")
        return
    end
    local equipInfo = getequipinfo(actor, itemId, 1)
    if table.isNullOrEmpty(equipInfo) then
        gameDebug.printTraceback("装备不存在")
        return
    end
    -- 判断是否有再生词条
    local regenerationData = API.GetItemData(actor, itemId, "regeneration")
    if table.isNullOrEmpty(regenerationData) then
        noticeTip.noticeinfo(actor, StringIdConst.NO_REGENERATION)
        return
    end
    -- 获取进化的最大等级
    local levelMax = ConfigDataManager.getTableValue("cfg_equip_regeneration", "levelMax", "id", equipInfo["cfgid"])
    if regenerationData[1]["level"] >= tonumber(levelMax) then
        noticeTip.noticeinfo(actor, StringIdConst.REGENERATION_EVOLUTION_MAX)
        return
    end
    -- 判断成功率
    local result, cost = this.checkRate(regenerationData[1]["group"], regenerationData[1]["level"] + 1)
    -- 判断道具是否充足
    local costMap = string.toIntIntMap(cost)
    if not Bag.checkCostMap(actor, costMap) then
        noticeTip.noticeinfo(actor, StringIdConst.TEXT346)
        return
    end
    Bag.costMap(actor, costMap, ItemAction.EQUIP_REGENERATION_EVOLUTION_COST)
    if result then
        -- 进化操作
        this.evolution(actor, itemId, regenerationData)
    end
    sendluamsg(actor, LuaMessageIdToClient.RES_REGENERATION_EVOLUTION_RESULT, result)
end

--- 为装备生成再生词条
--- @param actor any 角色
--- @param equipId number 装备id
--- @param tableInfo table 表格数据
function this.regeneration(actor, equipId, tableInfo)
    local group = tableInfo["group"]
    local tableList = ConfigDataManager.getTable("cfg_equip_regenerationGroup", "group", tonumber(group), "level", 1)
    local weightMap = {}
    for _, v in pairs(tableList) do
        weightMap[v] = tonumber(v["weight"])
    end
    local info = randombyweight(weightMap, 1)
    local att = info[1]["att"]
    local attrMap = string.toIntIntMap(att)
    local sequence = info[1]["sequence"]
    local regenerationData = {
        ["level"] = 1,
        ["group"] = group,
        ["sequence"] = sequence,
        ["attr"] = attrMap,
    }
    this.addRegeneration(actor, equipId, regenerationData)
    RoleAttr.addAndSaveRoleAttr(actor, RoleAttrKey.EQUIP_REGENERATION, attrMap)
end

--- 添加再生词条
--- @param actor any 角色
--- @param equipId number 装备id
--- @param regenerationData table 生成词条数据
function this.addRegeneration(actor, equipId, regenerationData)
    local info = API.GetItemData(actor, equipId, "regeneration")
    if table.isNullOrEmpty(info) then
        info = {}
    end
    table.insert(info, regenerationData)
    API.SetItemData(actor, equipId, "regeneration", info)
end

--- 进化再生词条
--- @param actor any 角色
--- @param equipId number 装备id
--- @param regenerationData table 再生词条数据
function this.evolution(actor, equipId, regenerationData)
    regenerationData[1]["level"] = regenerationData[1]["level"] + 1
    local att = ConfigDataManager.getTableValue("cfg_equip_regenerationGroup", "att",
            "group", regenerationData[1]["group"],
            "sequence", regenerationData[1]["sequence"],
            "level", regenerationData[1]["level"])
    local attrMap = string.toIntIntMap(att)
    regenerationData[1]["attr"] = attrMap
    RoleAttr.addAndSaveRoleAttr(actor, RoleAttrKey.EQUIP_REGENERATION, attrMap)
    API.SetItemData(actor, equipId, "regeneration", regenerationData)
end

--- 获取成功率和进化消耗
--- @param group number 再生组
--- @param level number 词条等级
--- @return boolean, string 成功率，消耗
function this.checkRate(group, level)
    local tableInfo = ConfigDataManager.getTable("cfg_equip_regenerationCost", "group", group, "level", level)
    local rate = tableInfo[1]["rate"]
    local cost = tableInfo[1]["cost"]
    return RandomUtil.isLuck(tonumber(rate)), cost
end

MessageRouter:register(LuaMessageIdToSever.REQ_REGENERATION, EquipRegeneration.regeneration)
MessageRouter:register(LuaMessageIdToSever.REQ_EQUIP_REGENERATION_EVOLUTION, EquipRegeneration.evolution)